package incremental
import("errors";"path/filepath";"sort";"strings")
type Rule struct{CheckID string `json:"check_id"`;Patterns []string `json:"patterns"`}
type Input struct{SchemaVersion string `json:"schema_version"`;ChangedPaths []string `json:"changed_paths"`;TrustedChecks []string `json:"trusted_checks"`;Rules []Rule `json:"rules"`;Release bool `json:"release"`}
type Selection struct{SchemaVersion string `json:"schema_version"`;Mode string `json:"mode"`;Checks []string `json:"checks"`;Reason string `json:"reason,omitempty"`}
func Select(in Input)(Selection,error){if in.SchemaVersion!="1.0.0"||len(in.TrustedChecks)==0{return Selection{},errors.New("incremental input is incomplete")};if in.Release{return full(in,"release mode requires full verification"),nil};picked:=map[string]bool{};for _,p:=range in.ChangedPaths{clean:=filepath.Clean(p);if p==""||filepath.IsAbs(p)||clean==".."||strings.HasPrefix(clean,"../"){return full(in,"changed path escapes repository"),nil};matches:=[]string{};for _,r:=range in.Rules{for _,pattern:=range r.Patterns{ok,err:=filepath.Match(pattern,clean);if err!=nil{return Selection{},err};if ok{matches=append(matches,r.CheckID);break}}};if len(matches)!=1{return full(in,"changed path impact is unknown or ambiguous"),nil};picked[matches[0]]=true};checks:=[]string{};trusted:=map[string]bool{};for _,c:=range in.TrustedChecks{trusted[c]=true};for c:=range picked{if !trusted[c]{return full(in,"mapped check is not trusted"),nil};checks=append(checks,c)};sort.Strings(checks);return Selection{SchemaVersion:"1.0.0",Mode:"incremental",Checks:checks},nil}
func full(in Input,reason string)Selection{checks:=append([]string{},in.TrustedChecks...);sort.Strings(checks);return Selection{SchemaVersion:"1.0.0",Mode:"full",Checks:checks,Reason:reason}}
